"use client"

import * as React from "react"
import { Collapsible as CollapsiblePrimitive } from "@base-ui/react/collapsible"
import { cn } from "@/lib/utils"

// Base UI className can be a state function; the wrappers feed it to cn(), so
// narrow it to a plain string (same treatment as the other ported files).
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Collapsible = CollapsiblePrimitive.Root

const CollapsibleTrigger = React.forwardRef<
  HTMLButtonElement,
  WithClassName<CollapsiblePrimitive.Trigger.Props>
>(({ className, ...props }, ref) => (
  <CollapsiblePrimitive.Trigger
    ref={ref}
    className={cn(
      "flex w-full items-center justify-between rounded-xl px-4 py-3",
      "backdrop-blur-md bg-white/[0.06] border border-white/10",
      "text-sm font-medium text-white/90",
      "transition-all duration-base",
      "hover:bg-white/[0.10] hover:shadow-[0_0_0.75rem_oklch(1_0_0/0.06)]",
      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[oklch(0.65_0.19_250)]/40",
      "[&[data-panel-open]]:rounded-b-none [&[data-panel-open]]:border-b-white/[0.04]",
      className
    )}
    {...props}
  />
))
CollapsibleTrigger.displayName = "CollapsibleTrigger"

const CollapsibleContent = React.forwardRef<
  HTMLDivElement,
  WithClassName<CollapsiblePrimitive.Panel.Props>
>(({ className, ...props }, ref) => (
  <CollapsiblePrimitive.Panel
    ref={ref}
    className={cn(
      "h-[var(--collapsible-panel-height)] overflow-hidden rounded-b-xl",
      "backdrop-blur-md bg-white/[0.04] border border-t-0 border-white/10",
      "transition-[height] duration-base ease-out data-starting-style:h-0 data-ending-style:h-0",
      className
    )}
    {...props}
  />
))
CollapsibleContent.displayName = "CollapsibleContent"

export { Collapsible, CollapsibleTrigger, CollapsibleContent }
